async (page) => {
  const results = [], errors = [], consoleErrors = [];
  const out = outputDir + '/';
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  const check = (condition, label, detail) => { if (!condition) throw new Error(`${label}: ${JSON.stringify(detail)}`); results.push({ passed: true, label, detail }); };
  const screenshot = name => page.screenshot({ path: `${out}${name}.png` });
  const word = text => page.locator('[data-word]').filter({ hasText: new RegExp(`^${text}[,.!?]?$`, 'i') }).first();
  const close = async () => { if (await page.locator('.dictionary-popover').count()) { await page.keyboard.press('Escape'); await page.waitForSelector('.dictionary-popover', { state: 'detached' }); } };
  const chooseChapter = async index => { await close(); await page.getByRole('button', { name: '章节目录', exact: true }).click(); await page.locator('.chapter-list button').nth(index).click(); await page.waitForTimeout(120); };
  const clickWord = async text => { await word(text).click(); await page.waitForTimeout(450); };
  const bounds = async label => { const r = await page.locator('.dictionary-popover').boundingBox(), v = page.viewportSize(); check(r && r.x >= 15 && r.y >= 15 && r.x + r.width <= v.width - 15 && r.y + r.height <= v.height - 15, label, { r, v }); };
  await page.goto('http://127.0.0.1:4173/');
  await page.evaluate(() => localStorage.clear()); await page.reload();
  await page.waitForSelector('[data-word]');
  await page.waitForTimeout(150);
  for (const [width, height] of [[1440,900],[1920,1080],[1366,768]]) {
    await page.setViewportSize({ width, height }); await page.waitForTimeout(120);
    await screenshot(`reader-${width}`);
    const before = await page.locator('.reading-viewport').boundingBox();
    await clickWord('acknowledged'); await bounds(`卡片边界 ${width}×${height}`);
    const after = await page.locator('.reading-viewport').boundingBox();
    check(JSON.stringify(before) === JSON.stringify(after), `打开词典无正文布局位移 ${width}`, { before, after });
    check(await page.locator('.senses .sense').count() === 3, '主释义与两条其他释义默认可见');
    check(!await page.locator('.translation-result').count(), '默认不自动翻译');
    await screenshot(`dictionary-${width}`); await close();
  }
  await page.setViewportSize({ width:1440,height:900 }); await page.waitForTimeout(120);
  for (const side of ['left','right','bottom']) {
    const token = await page.evaluate(side => { const v=document.querySelector('.reading-viewport').getBoundingClientRect(); const list=[...document.querySelectorAll('[data-word]')].filter(e=>{const r=e.getBoundingClientRect();return r.left>=v.left && r.right<=v.right && r.top>=v.top && r.bottom<=v.bottom});list.sort((a,b)=>{const x=a.getBoundingClientRect(),y=b.getBoundingClientRect();return side==='left'?x.left-y.left:side==='right'?y.right-x.right:y.bottom-x.bottom});return list[0].dataset.offset; }, side);
    await page.locator(`[data-offset="${token}"]`).click(); await page.waitForTimeout(450); await bounds(`单词位于${side}边界`); await screenshot(`anchor-${side}`); await close();
  }
  await clickWord('acknowledged');
  await page.getByRole('button', { name:'更多释义（2）' }).click();
  check(await page.locator('.senses .sense').count() === 5, '展开剩余词义');
  await bounds('展开词义后仍在视口内'); await screenshot('dictionary-expanded');
  await page.locator('.sense').nth(1).click();
  check(await page.locator('.sense').nth(1).getAttribute('aria-pressed') === 'true', '可切换当前释义');
  await page.getByRole('button',{ name:'翻译例句', exact:true }).click();
  await page.waitForSelector('.translation-status'); await screenshot('translation-loading');
  await page.waitForSelector('.translation-result'); await screenshot('translation-success');
  await page.getByRole('button',{ name:'收藏', exact:true }).click();
  await page.getByRole('button',{ name:'已收藏', exact:true }).waitFor();
  check(await page.locator('.dictionary-popover').count() === 1, '收藏成功卡片保留'); await screenshot('word-saved');
  await page.getByRole('button',{ name:'已收藏', exact:true }).click();
  await page.getByRole('button',{ name:'保留', exact:true }).click();
  await close();
  await page.getByRole('button',{ name:'下一页', exact:true }).click();
  const pageBefore = await page.locator('.page-count').innerText();
  const offsetBefore = await page.evaluate(()=>JSON.parse(localStorage.getItem('readict-prototype-v1')).progress.pride.offset);
  check(offsetBefore > 0, '翻页保存稳定字符偏移', offsetBefore);
  await page.reload(); await page.waitForSelector('.page-count'); await page.waitForTimeout(120);
  check((await page.locator('.page-count').innerText())===pageBefore, '刷新恢复阅读位置', {expected:pageBefore,actual:await page.locator('.page-count').innerText(), offsetBefore});
  await page.getByRole('button',{ name:'阅读设置', exact:true }).click();
  const boxBefore = await page.locator('.reading-viewport').boundingBox(); await screenshot('reading-settings');
  await page.getByRole('button',{ name:'字号 24', exact:true }).click(); await page.waitForTimeout(120);
  const kept = await page.locator(`[data-offset="${offsetBefore}"]`).evaluate(el=>{const r=el.getBoundingClientRect(),v=document.querySelector('.reading-viewport').getBoundingClientRect();return r.left>=v.left-1 && r.right<=v.right+1;});
  check(kept, '改变字号后原位置仍在当前页面');
  await page.getByRole('button',{ name:'宽松宽度', exact:true }).click();
  await page.getByRole('button',{ name:'深色', exact:true }).click(); await screenshot('reader-dark');
  await page.getByRole('button',{ name:'暖色', exact:true }).click(); await page.getByRole('button',{ name:'字号 20', exact:true }).click();
  await page.getByRole('button',{ name:'标准宽度', exact:true }).click(); await page.locator('.reader-panel').getByRole('button',{name:'关闭',exact:true}).click();
  check(boxBefore.width === 660, '目录与设置保持标准正文宽度');
  await chooseChapter(2); await screenshot('reader-demo-chapter');
  await clickWord('runs'); await page.getByRole('button',{name:'收藏',exact:true}).click(); await page.getByRole('button',{name:'已收藏',exact:true}).waitFor(); await close();
  await page.locator('[data-word]').filter({hasText:/^runs[,.!?]?$/i}).nth(1).click(); await page.waitForSelector('.entry-title');
  check(await page.getByRole('button',{name:'收藏本句',exact:true}).count()===1,'同词不同语境显示收藏本句');
  await page.getByRole('button',{name:'收藏本句',exact:true}).click(); await page.getByRole('button',{name:'已收藏',exact:true}).waitFor(); await close();
  await clickWord('running'); await page.getByRole('button',{name:'收藏本句',exact:true}).click(); await page.getByRole('button',{name:'已收藏',exact:true}).waitFor(); await close();
  const saved = await page.evaluate(()=>JSON.parse(localStorage.getItem('readict-prototype-v1')).favorites);
  check(saved.filter(f=>f.lemma==='run').length===1 && saved.find(f=>f.lemma==='run').contexts.length===3,'run/runs/running 归并为一个主体并关联三个句子');
  await clickWord('extraordinary'); await page.getByRole('button',{name:/更多释义/}).click(); await bounds('长原句与长释义卡片边界'); await screenshot('long-content'); await close();
  // Larger page height keeps deterministic error fixtures on one page.
  await page.setViewportSize({width:1440,height:1600}); await page.waitForTimeout(120);
  await clickWord('timeout'); check(await page.getByRole('button',{name:'重试查询',exact:true}).count()===1,'词典超时保留原文'); await screenshot('lookup-error');
  await page.getByRole('button',{name:'重试查询',exact:true}).click(); await page.waitForSelector('.entry-title'); await close();
  await clickWord('mystery'); check((await page.locator('.context-sentence').textContent()).includes('mystery'),'无词条仍显示原文'); await screenshot('lookup-empty'); await close();
  await clickWord('storm'); await page.getByRole('button',{name:'翻译例句',exact:true}).click(); await page.waitForSelector('.translation-status.error'); await screenshot('translation-error');
  await page.getByRole('button',{name:'重试翻译',exact:true}).click(); await page.waitForSelector('.translation-result'); await close();
  await clickWord('archive'); await page.getByRole('button',{name:'收藏',exact:true}).click(); await page.waitForTimeout(300);
  check(await page.getByRole('button',{name:'收藏',exact:true}).count()===1,'收藏失败不显示成功'); await screenshot('favorite-error');
  await page.getByRole('button',{name:'收藏',exact:true}).click(); await page.getByRole('button',{name:'已收藏',exact:true}).waitFor(); await close();
  await word('children').click(); await word('runs').click(); await page.waitForTimeout(450);
  check(await page.locator('.entry-title h2').textContent()==='run','快速切换查询不串词'); await close();
  await word('children').click(); await page.keyboard.press('Escape'); await page.waitForTimeout(450); check(await page.locator('.dictionary-popover').count()===0,'关闭后迟到请求不重开卡片');
  await page.setViewportSize({width:1440,height:900}); await page.waitForTimeout(120);
  await page.getByRole('button',{name:'章节目录',exact:true}).click(); await screenshot('contents'); await page.keyboard.press('Escape');
  await page.getByRole('button',{name:'打开收藏',exact:true}).click(); await screenshot('favorites-words');
  await page.getByRole('tab',{name:'句子',exact:true}).click(); await screenshot('favorites-sentences');
  await page.getByRole('tab',{name:'单词',exact:true}).click(); await page.getByRole('button',{name:/^run /}).click(); await screenshot('favorite-detail');
  await page.keyboard.press('Escape');
  await page.getByRole('textbox',{name:'搜索收藏'}).fill('running'); check(await page.locator('.favorite-word-row').count()===1,'收藏搜索匹配原句');
  await page.getByRole('textbox',{name:'搜索收藏'}).fill('');
  await page.getByRole('link',{name:'我的书架',exact:true}).click(); await screenshot('bookshelf');
  await page.getByRole('button',{name:'导入 EPUB',exact:true}).click();
  await page.getByLabel('选择 EPUB 文件').setInputFiles({name:'bad.txt',mimeType:'text/plain',buffer:Buffer.from('test')});
  check((await page.locator('.import-status').textContent()).includes('.epub'),'导入格式检查'); await screenshot('import-error');
  await page.getByLabel('选择 EPUB 文件').setInputFiles({name:'demo.epub',mimeType:'application/epub+zip',buffer:Buffer.from('demo')}); await screenshot('import-loading');
  await page.getByRole('button',{name:'返回书架',exact:true}).click(); check(await page.locator('.book-item').count()===3,'模拟导入加入书架');
  await page.getByRole('button',{name:'删除 Pride and Prejudice',exact:true}).click(); await page.getByRole('button',{name:'确认删除',exact:true}).click();
  await page.getByRole('link',{name:/^收藏/}).click(); await page.getByRole('tab',{name:'句子',exact:true}).click();
  check(await page.getByText('原书已删除',{exact:true}).count()>=1,'删除书籍仍保留收藏快照'); await screenshot('favorites-book-deleted');
  await page.getByRole('tab',{name:'单词',exact:true}).click(); await page.getByRole('button',{name:'取消收藏 run',exact:true}).click(); await page.getByRole('button',{name:'确认删除',exact:true}).click();
  check((await page.evaluate(()=>JSON.parse(localStorage.getItem('readict-prototype-v1')).favorites)).every(f=>f.lemma!=='run'),'取消收藏删除主体和全部语境');
  // Restore seeded demo for final screenshots; no fabricated user collections.
  await page.evaluate(()=>{ const s=JSON.parse(localStorage.getItem('readict-prototype-v1'));s.removedBooks=[];s.progress={};s.preferences={font:'Georgia',fontSize:20,lineHeight:1.8,width:660,theme:'warm'};localStorage.setItem('readict-prototype-v1',JSON.stringify(s));});
  await page.goto('http://127.0.0.1:4173/#/reader/pride'); await page.reload(); await page.waitForSelector('[data-word]');
  await page.setViewportSize({width:390,height:844}); await page.waitForTimeout(150); await screenshot('reader-mobile');
  await clickWord('acknowledged'); await bounds('390px 窄屏卡片边界'); await screenshot('dictionary-mobile'); await close();
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'窄屏无横向页面溢出');
  await page.getByRole('button',{name:'阅读设置',exact:true}).click(); await screenshot('settings-mobile'); await page.keyboard.press('Escape');
  await page.reload(); await page.waitForSelector('[data-word]'); check(await page.evaluate(()=>JSON.parse(localStorage.getItem('readict-prototype-v1')).preferences.theme)==='warm','刷新持久化偏好');
  await page.setViewportSize({width:1440,height:900}); await page.waitForTimeout(120); await screenshot('reader-final'); await clickWord('acknowledged'); await screenshot('dictionary-final');
  check(errors.length===0,'无浏览器脚本异常',errors); check(consoleErrors.length===0,'无浏览器控制台错误',consoleErrors);
  return { passed: results.length, results, errors, consoleErrors };
}
